class Solution {
public:
    int sumFourDivisors(vector<int>& nums) {
        int total = 0;
        for (int x : nums) {
            int count = 0, sum = 0;
            for (int d = 1; d * d <= x; ++d) {
                if (x % d) continue;
                int other = x / d;
                count += (d == other ? 1 : 2);
                sum += d + (d == other ? 0 : other);
                if (count > 4) break;
            }
            if (count == 4) total += sum;
        }
        return total;
    }
};
